def game(A, B):
    if A < 1 or B < 1:
        return "Non-drinkers can't play"

    turn = 1
    mike_total = 0
    joe_total = 0

    while True:
        if turn % 2 == 1:  # Mike's turn
            if mike_total + turn > A:
                return "Joe"
            mike_total += turn
        else:  # Joe's turn
            if joe_total + turn > B:
                return "Mike"
            joe_total += turn

        turn += 1
